with valid_employees as (select *, if(is_remote, 'Yes', 'No') as is_remote_label from employees where not is_remote or manager_id is null), summary as (select job_title, max(hire_date) as last_hire_date, round(stddev(salary), 2) as stddev_salary from valid_employees group by job_title) select job_title, last_hire_date, stddev_salary from summary where stddev_salary >= 77 order by stddev_salary desc, 2
